create table public.reviews (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade, order_id uuid references public.orders(id) on delete set null, customer_name text not null, restaurant_rating numeric(2,1) not null check (restaurant_rating between 1 and 5), comment text, owner_reply text, created_at timestamptz not null default now());
create table public.media_assets (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade, kind text not null check (kind in ('logo','cover','menu_item','gallery','video')), storage_path text not null, alt_text text, created_at timestamptz not null default now());
alter table public.reviews enable row level security;alter table public.media_assets enable row level security;
create policy "Public reads restaurant reviews" on public.reviews for select using (exists (select 1 from public.restaurants r where r.id = restaurant_id and r.is_published));
create policy "Owners manage restaurant reviews" on public.reviews for all using (exists (select 1 from public.restaurants r where r.id = restaurant_id and r.owner_id = (select auth.uid()))) with check (exists (select 1 from public.restaurants r where r.id = restaurant_id and r.owner_id = (select auth.uid())));
create policy "Owners manage media" on public.media_assets for all using (exists (select 1 from public.restaurants r where r.id = restaurant_id and r.owner_id = (select auth.uid()))) with check (exists (select 1 from public.restaurants r where r.id = restaurant_id and r.owner_id = (select auth.uid())));
create policy "Public reads media" on public.media_assets for select using (exists (select 1 from public.restaurants r where r.id = restaurant_id and r.is_published));
